//! PipeWire bluez5 A2DP codec plugin for Samsung SSC.
//!
//! Built as `libspa-codec-bluez5-<slot>.so`, it is loaded by PipeWire's
//! bluez5 codec loader like the in-tree codecs (`a2dp-codec-*.c`). The ABI is
//! PipeWire's private `struct media_codec`, generated by bindgen from the
//! headers vendored for the PipeWire version in `pipewire/`.

pub mod ssc;

#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unsafe_op_in_unsafe_fn
)]
#[allow(clippy::all)]
mod sys {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

mod slot {
    include!(concat!(env!("OUT_DIR"), "/slot.rs"));
}

mod codec;
mod log;
mod plugin;
mod pod;

pub use slot::SLOT;

/// Lets `install.sh` and `crossc-cli update` tell this plugin and its version
/// apart from whatever else sits in the codec slot, without loading it.
#[used]
static VERSION_MARKER: &[u8] = concat!(
    "crossc-linux-plugin-version=",
    env!("CARGO_PKG_VERSION"),
    "\0"
)
.as_bytes();
